// Command gziphandler writes testdata/golden/gziphandler.golden for pbs-server: what
// github.com/NYTimes/gziphandler v1.1.1 does, as Prebid Server's server/server.go uses it
// (gziphandler.GzipHandler when compression.response.enable_gzip is set) and with its other
// options. GOC-HTTPSRV wrote it (cd96690b) for the port this crate replaces; the prebid and
// encodings rows are the pins of crates/server/tests/compression.rs. Run it from the directory of
// this module (crates/server/testdata/go) with the Go toolchain Prebid ships (go1.26.2):
//
//	GOTOOLCHAIN=go1.26.2 go run ./gziphandler
//
// Each line is "<kind> <quoted input> <quoted output>":
//
//	encodings    the Accept-Encoding value a request carries: the codings parseEncodings
//	             returns (sorted, with their q values), its error, and whether acceptsGzip holds
//	contenttype  the ContentTypes option (values joined by "\x1f"), "\x1e" and the Content-Type a
//	             handler sets before writing 2000 bytes: whether the response is gzipped
//	config       options (see options): the error GzipHandlerWithOpts returns
//	gzip         options, "\x1f", the request's Accept-Encoding, "\x1f" and a plan (see plan): what
//	             the handler wrapped by those options does to the ResponseRecorder under it
//	prebid       enable_gzip, "\x1f", Accept-Encoding, "\x1f" and a plan, through Prebid's
//	             getCompressionEnabledHandler
package main

import (
	"flag"
	"fmt"
	"hash/crc32"
	"math/rand"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	_ "unsafe" // for go:linkname

	"github.com/NYTimes/gziphandler"
)

func main() {
	out := flag.String("out", defaultOut(), "golden file to write")
	flag.Parse()
	if err := os.WriteFile(*out, []byte(generate()), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// generate returns the golden's text.
func generate() string {
	var b strings.Builder
	b.WriteString("# Generated by testdata/go/gziphandler (go1.26.2, github.com/NYTimes/gziphandler v1.1.1). Do not edit.\n")
	row := func(kind, in, out string) {
		fmt.Fprintf(&b, "%s %s %s\n", kind, strconv.Quote(in), strconv.Quote(out))
	}
	for _, s := range encodingInputs() {
		row("encodings", s, encodings(s))
	}
	for _, tt := range contentTypeInputs() {
		row("contenttype", strings.Join(tt.types, "\x1f")+"\x1e"+tt.ct, contentType(tt.types, tt.ct))
	}
	for _, o := range configInputs() {
		row("config", o, configError(o))
	}
	for _, tt := range gzipInputs() {
		row("gzip", tt.opts+"\x1f"+tt.accept+"\x1f"+tt.plan, runGzip(tt.opts, tt.accept, tt.plan))
	}
	for _, enable := range []bool{false, true} {
		for _, accept := range []string{"gzip", ""} {
			for _, plan := range []string{"", "w10", "w2000", "z5000", "s204", "tjson.w1400"} {
				in := strconv.FormatBool(enable) + "\x1f" + accept + "\x1f" + plan
				row("prebid", in, runPrebid(enable, accept, plan))
			}
		}
	}
	return b.String()
}

func defaultOut() string {
	_, file, _, _ := runtime.Caller(0)
	return filepath.Join(filepath.Dir(file), "..", "..", "golden", "gziphandler.golden")
}

// encodingInputs are TestParseEncodings' examples, hand-picked values and combinations of
// codings, parameters and separators.
func encodingInputs() []string {
	in := []string{
		"compress, gzip", "", "*", "compress;q=0.5, gzip;q=1.0", "gzip;q=1.0, identity; q=0.5, *;q=0",
		"AAA;q=1", "BBB ; q = 2", "gzip", "GZIP", "Gzip", "gzip;q=0", "gzip;q=0.001", "gzip;q=-1",
		"gzip;q=2", "gzip;q=abc", "gzip;q=", "gzip;Q=0", "gzip; q=0", "gzip ;q=0", "gzip;q = 0",
		"gzip;q=NaN", "gzip;q=inf", "gzip;q=-Inf", "gzip;q=1e400", "gzip;q=-1e400", "gzip;q=0x1p-2",
		"gzip;q=1_0", "gzip;q=.5", "gzip;q=5.", "gzip;q=0;foo", "gzip;q=abc;q=0.5", "gzip;q=0.5;q=abc",
		"gzip;q=0, gzip", "gzip, gzip;q=0", "gzip, gzip;q=abc", "gzip,,", ",gzip", " , ", ";q=1",
		"deflate", "x-gzip", "gzip2", " gzip", "gzip ", "\u0085gzip;q=1", "gzİp", "GZİP",
		"gzip;level=9", "gzip;", "gzip;;q=0", "gzip; q=0.0000001", "gzip;q=1.0000001", "gzip;q=-0",
		"identity;q=0, *;q=0", "br;q=1.0, gzip;q=0.8, *;q=0.1", "gzip\t;\tq=0.5",
	}
	codings := []string{"gzip", "GZIP", "Gzip", "deflate", "br", "*", "identity", "", " ", "x-gzip", "gzİp", "\tgzip"}
	params := []string{
		"", "", ";q=0", ";q=1", ";q=0.5", "; q=0.001", ";q=1.5", ";q=-1", ";q=abc", ";q=", ";Q=0.5",
		"; q = 0.5", ";q=NaN", ";q=inf", ";q=1e400", ";q=0x1p-1", ";q=.5", ";level=1", ";", ";;q=0",
		";q=0;x", ";x;q=0",
	}
	seps := []string{",", ", ", " ,", ",,", ", \t"}
	rnd := rand.New(rand.NewSource(21))
	for i := 0; i < 1500; i++ {
		var b strings.Builder
		for j := rnd.Intn(4); j >= 0; j-- {
			b.WriteString(codings[rnd.Intn(len(codings))])
			b.WriteString(params[rnd.Intn(len(params))])
			if j > 0 {
				b.WriteString(seps[rnd.Intn(len(seps))])
			}
		}
		in = append(in, b.String())
	}
	return in
}

// encodings reports what gziphandler makes of an Accept-Encoding value: the codings of
// parseEncodings, and whether a request carrying it gets a gzip writer.
func encodings(s string) string {
	c, err := parseEncodings(s)
	keys := make([]string, 0, len(c))
	for k := range c {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	for _, k := range keys {
		fmt.Fprintf(&b, "%s=%s ", strconv.Quote(k), strconv.FormatFloat(c[k], 'g', -1, 64))
	}
	errText := "<nil>"
	if err != nil {
		errText = err.Error()
	}
	accepts := acceptsGzip(s)
	if accepts != (c["gzip"] > 0.0) {
		panic("acceptsGzip disagrees with parseEncodings for " + strconv.Quote(s))
	}
	fmt.Fprintf(&b, "err=%s accepts=%t", errText, accepts)
	return b.String()
}

// acceptsGzip reports whether gziphandler compresses for a request with this Accept-Encoding.
func acceptsGzip(s string) bool {
	req := httptest.NewRequest("GET", "/", nil)
	req.Header.Set("Accept-Encoding", s)
	gzipped := false
	gziphandler.GzipHandler(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, gzipped = w.(*gziphandler.GzipResponseWriter)
	})).ServeHTTP(httptest.NewRecorder(), req)
	return gzipped
}

// parseEncodings is gzip.go's (v1.1.1, lines 466-484), which the package does not export.
//
//go:linkname parseEncodings github.com/NYTimes/gziphandler.parseEncodings
func parseEncodings(s string) (map[string]float64, error)

type contentTypeInput struct {
	types []string
	ct    string
}

// contentTypeInputs are contentTypeTests' cases and combinations of option values and response
// types.
func contentTypeInputs() []contentTypeInput {
	in := []contentTypeInput{
		{nil, ""},
		{[]string{"application/json"}, "application/json"},
		{[]string{"application/json"}, "text/xml"},
		{[]string{"application/json"}, "application/json; charset=utf-8"},
		{[]string{"application/json; charset=utf-8"}, "application/json; charset=ascii"},
		{[]string{"application/json; charset=utf-8"}, "application/json; charset=utf-8"},
		{[]string{"application/json; charset=ascii"}, "application/json"},
		{[]string{"application/json"}, "Application/Json"},
		{[]string{"application/json;            charset=utf-8"}, "application/json;charset=utf-8"},
	}
	types := []string{
		"application/json", "application/json; charset=utf-8", "text/html", "TEXT/HTML; Charset=UTF-8",
		"bad/", "", "text/html; a=1; b=2", "text/html; b=2; a=1", "text/plain; charset=utf-8", "text/plain",
	}
	cts := []string{
		"application/json", "Application/Json", "application/json; charset=utf-8",
		"application/json;charset=utf-8", "application/json; charset=ascii", "text/html",
		"text/html; charset=utf-8", "text/html; a=1; b=2", "text/html; b=2; a=1; c=3", "bad", "",
		"text/html;", "text/html; a=\"1\"", "text/html; A=1; B=2", "text/plain",
	}
	for i := range types {
		for _, ct := range cts {
			in = append(in, contentTypeInput{[]string{types[i]}, ct})
			in = append(in, contentTypeInput{[]string{types[i], types[(i+3)%len(types)]}, ct})
		}
	}
	in = append(in, contentTypeInput{[]string{}, "text/html"}, contentTypeInput{[]string{"bad/"}, "bad/"})
	return in
}

func contentType(types []string, ct string) string {
	wrap, err := gziphandler.GzipHandlerWithOpts(gziphandler.ContentTypes(types))
	if err != nil {
		return "err=" + err.Error()
	}
	h := wrap(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		if ct != "" {
			w.Header().Set("Content-Type", ct)
		}
		w.Write(pattern(2000))
	}))
	req := httptest.NewRequest("GET", "/", nil)
	req.Header.Set("Accept-Encoding", "gzip")
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if rec.Header().Get("Content-Encoding") == "gzip" {
		return "gzip " + rec.Header().Get("Content-Type")
	}
	return "plain " + rec.Header().Get("Content-Type")
}

// configInputs are the option sets the config rows validate.
func configInputs() []string {
	var in []string
	for level := -3; level <= 10; level++ {
		in = append(in, fmt.Sprintf("level=%d", level))
	}
	for _, min := range []int{-1, 0, 1, 1400} {
		in = append(in, fmt.Sprintf("min=%d", min), fmt.Sprintf("level=10,min=%d", min))
	}
	return append(in, "", "types=", "types=bad/", "types=application/json\x1etext/html", "must=-42", "must=5")
}

// handlerOf builds the middleware of an option spec, "k=v,k=v": level is CompressionLevel, min
// MinSize and types ContentTypes (values joined by "\x1e"); "must=N" is
// MustNewGzipLevelHandler(N), and "" is GzipHandler.
func handlerOf(spec string) (func(http.Handler) http.Handler, error) {
	if spec == "" {
		return gziphandler.GzipHandler, nil
	}
	opts := optionList(gziphandler.MinSize(0))[:0]
	for _, kv := range strings.Split(spec, ",") {
		k, v, _ := strings.Cut(kv, "=")
		switch k {
		case "level":
			opts = append(opts, gziphandler.CompressionLevel(atoi(v)))
		case "min":
			opts = append(opts, gziphandler.MinSize(atoi(v)))
		case "types":
			var types []string
			if v != "" {
				types = strings.Split(v, "\x1e")
			}
			opts = append(opts, gziphandler.ContentTypes(types))
		case "must":
			return gziphandler.MustNewGzipLevelHandler(atoi(v)), nil
		}
	}
	return gziphandler.GzipHandlerWithOpts(opts...)
}

// optionList makes a slice of gziphandler options, whose type the package does not export.
func optionList[T any](opts ...T) []T { return opts }

// configError is the error handlerOf returns, or what it panics with.
func configError(spec string) (result string) {
	defer func() {
		if p := recover(); p != nil {
			result = fmt.Sprintf("panic=%v", p)
		}
	}()
	if _, err := handlerOf(spec); err != nil {
		return err.Error()
	}
	return "<nil>"
}

// wrapper is the middleware of a valid option spec.
func wrapper(spec string) func(http.Handler) http.Handler {
	wrap, err := handlerOf(spec)
	if err != nil {
		panic(err)
	}
	return wrap
}

type gzipInput struct{ opts, accept, plan string }

// gzipOps are the steps the generated plans combine.
var gzipOps = []string{
	"n", "w10", "w1399", "w1400", "w3000", "z2000", "z20000", "f", "s200", "s204", "s304", "s404",
	"tnil", "tempty", "tjson", "thtml", "l100", "l1400", "labc", "l-1", "egzip", "p",
}

// gzipOps3 are the steps of the three-step plans.
var gzipOps3 = []string{"n", "w700", "w1000", "z3000", "f", "s404", "l15000", "egzip", "p"}

func gzipInputs() []gzipInput {
	var in []gzipInput
	add := func(opts, accept, plan string) { in = append(in, gzipInput{opts, accept, plan}) }
	plans := []string{""}
	for _, a := range gzipOps {
		plans = append(plans, a)
		for _, b := range gzipOps {
			plans = append(plans, a+"."+b)
		}
	}
	for _, a := range gzipOps3 {
		for _, b := range gzipOps3 {
			for _, c := range gzipOps3 {
				plans = append(plans, a+"."+b+"."+c)
			}
		}
	}
	plans = append(plans,
		// TestGzipHandlerDoubleWriteHeader, TestStatusCodes, TestFlushBeforeWrite,
		// TestIgnoreSubsequentWriteHeader and TestDontWriteWhenNotWrittenTo.
		"l15000.s304.n", "s404.bnotfound", "s404.f.w3000", "s500.s404", "",
		// TestGzipHandlerContentLength's writes.
		"l3000.w200.w2800", "w200.w2800", "l3000.n",
		// TestGzipHandlerMinSize's writes, one byte at a time.
		strings.TrimSuffix(strings.Repeat("w1.", 127), "."), strings.TrimSuffix(strings.Repeat("w1.", 128), "."),
		"w1399.w1", "w1.w1399", "w1000.w1000.w1000", "z1000.f.z1000.f.z1000", "w2000.f.f.w2000.f",
		"z70000", "z70000.f.z5000", "l1400.n.w10", "l5000.n.w10", "l5000.n.n", "egzip.w3000.f",
		"tnil.w2000", "tempty.w2000", "thtml.w2000", "bhtml.w2000", "bhtml.w1399", "s304.w2000",
		"s204.w2000.x10", "x10", "x2000", "x1400.x1", "w1400.x1", "l99999999999999999999.w10",
		"l-99999999999999999999.w10", "l+1400.w10", "l 1400.w10", "l1400 .w10", "l0.w10", "l0.w2000",
		"eidentity.w2000", "e.w2000", "s201.w1.s202.w1500", "w10.p", "w2000.p", "z70000.p", "s202.p",
		"f.p", "w2000.f.p", "s200.f.w10",
	)
	for _, p := range plans {
		add("", "gzip", p)
	}
	small := []string{"", "n", "w10", "w127", "w128", "w1399", "w1400", "z3000", "s204", "tjson.w2000",
		"thtml.w2000", "f.w10", "w10.f", "l100.w10", "egzip.w2000", "w10.p"}
	for _, opts := range []string{"min=0", "min=128", "level=1", "level=9", "level=-1", "level=5,min=10", "types=application/json", "types=text/html; charset=utf-8", "min=1400"} {
		for _, p := range small {
			add(opts, "gzip", p)
		}
	}
	for _, accept := range []string{"", "deflate", "gzip;q=0", "*", "gzip;q=0.5", "x, GZIP"} {
		for _, p := range []string{"", "w10", "w2000", "z5000", "s304.n", "f.w10", "w10.p"} {
			add("", accept, p)
		}
	}
	return in
}

// tracer is the ResponseWriter under the gzip handler: a ResponseRecorder that records the calls
// it gets.
type tracer struct {
	rec   *httptest.ResponseRecorder
	calls []string
}

func (t *tracer) Header() http.Header { return t.rec.Header() }

func (t *tracer) WriteHeader(code int) {
	t.calls = append(t.calls, fmt.Sprintf("H%d", code))
	t.rec.WriteHeader(code)
}

func (t *tracer) Write(b []byte) (int, error) {
	n, err := t.rec.Write(b)
	call := fmt.Sprintf("W%d", len(b))
	if err != nil {
		call += "!" + err.Error()
	}
	t.calls = append(t.calls, call)
	return n, err
}

func (t *tracer) Flush() {
	t.calls = append(t.calls, "F")
	t.rec.Flush()
}

// planBodies are the bodies of a plan's b steps.
var planBodies = map[string]string{"html": "<html>", "notfound": "404 page not found\n"}

// runPlan runs the dot-separated steps of spec on w: n writes nil, wN N pattern bytes, zN N
// incompressible bytes, xN N pattern bytes (as w), bNAME planBodies[NAME], f flushes, sN writes
// the status code N, tX sets the Content-Type (to nil for "nil", "" for "empty", else
// "application/json" or "text/html; charset=utf-8"), lX sets the Content-Length, eX the
// Content-Encoding, and p panics. It appends the result of each write to results.
func runPlan(w http.ResponseWriter, spec string, results *[]string) {
	write := func(op string, b []byte) {
		n, err := w.Write(b)
		r := fmt.Sprintf("%s=%d", op, n)
		if err != nil {
			r += "!" + err.Error()
		}
		*results = append(*results, r)
	}
	h := w.Header()
	for _, op := range strings.Split(spec, ".") {
		if op == "" {
			continue
		}
		arg := op[1:]
		switch op[0] {
		case 'n':
			write(op, nil)
		case 'w', 'x':
			write(op, pattern(atoi(arg)))
		case 'z':
			write(op, noise(atoi(arg)))
		case 'b':
			write(op, []byte(planBodies[arg]))
		case 'f':
			w.(http.Flusher).Flush()
		case 's':
			w.WriteHeader(atoi(arg))
		case 't':
			switch arg {
			case "nil":
				h["Content-Type"] = nil
			case "empty":
				h.Set("Content-Type", "")
			case "json":
				h.Set("Content-Type", "application/json")
			case "html":
				h.Set("Content-Type", "text/html; charset=utf-8")
			}
		case 'l':
			h.Set("Content-Length", arg)
		case 'e':
			h.Set("Content-Encoding", arg)
		case 'p':
			panic("boom")
		}
	}
}

// serve runs h for a GET request with this Accept-Encoding (none when empty) over a tracer and
// prints what happened: the calls the tracer got, the results of the plan's writes, a panic, and
// the recorder's code, header map and body.
func serve(h func(plan *[]string) http.Handler, accept string) (out string) {
	req := httptest.NewRequest("GET", "/", nil)
	if accept != "" {
		req.Header.Set("Accept-Encoding", accept)
	}
	t := &tracer{rec: httptest.NewRecorder()}
	var results []string
	panicked := "none"
	func() {
		defer func() {
			if p := recover(); p != nil {
				panicked = fmt.Sprint(p)
			}
		}()
		h(&results).ServeHTTP(t, req)
	}()
	return fmt.Sprintf("calls=[%s] writes=[%s] panic=%s code=%d flushed=%t header:%s body=%s",
		strings.Join(t.calls, " "), strings.Join(results, " "), panicked, t.rec.Code, t.rec.Flushed,
		formatHeader(t.rec.HeaderMap), body(t.rec.Body.Bytes()))
}

func planHandler(spec string, results *[]string) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { runPlan(w, spec, results) })
}

func runGzip(opts, accept, spec string) string {
	wrap := wrapper(opts)
	return serve(func(results *[]string) http.Handler { return wrap(planHandler(spec, results)) }, accept)
}

// getCompressionEnabledHandler is server/server.go's (lines 120-125), which takes a
// config.CompressionInfo.
func getCompressionEnabledHandler(h http.Handler, enableGzip bool) http.Handler {
	if enableGzip {
		h = gziphandler.GzipHandler(h)
	}
	return h
}

func runPrebid(enable bool, accept, spec string) string {
	return serve(func(results *[]string) http.Handler {
		return getCompressionEnabledHandler(planHandler(spec, results), enable)
	}, accept)
}

// body prints a response body: its length and CRC-32, and the bytes when there are few.
func body(b []byte) string {
	s := fmt.Sprintf("%d/%08x", len(b), crc32.ChecksumIEEE(b))
	if len(b) <= 48 {
		s += "/" + strconv.Quote(string(b))
	}
	return s
}

// pattern is n bytes cycling through the alphabet.
func pattern(n int) []byte {
	b := make([]byte, n)
	for i := range b {
		b[i] = byte('a' + i%26)
	}
	return b
}

// noise is n bytes of a xorshift64 sequence, which deflate cannot shrink.
func noise(n int) []byte {
	b := make([]byte, n)
	x := uint64(0x9E3779B97F4A7C15)
	for i := range b {
		x ^= x << 13
		x ^= x >> 7
		x ^= x << 17
		b[i] = byte(x >> 56)
	}
	return b
}

func atoi(s string) int {
	n, _ := strconv.Atoi(s)
	return n
}

// formatHeader lists a header map: sorted keys, one " key=quoted-value" per value, and
// " key=<none>" for a key without values.
func formatHeader(h http.Header) string {
	keys := make([]string, 0, len(h))
	for k := range h {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	for _, k := range keys {
		if len(h[k]) == 0 {
			fmt.Fprintf(&b, " %s=<none>", k)
		}
		for _, v := range h[k] {
			fmt.Fprintf(&b, " %s=%s", k, strconv.Quote(v))
		}
	}
	return b.String()
}
